use core::f32;
use std::{fmt::Write as _, io::Cursor};

use egui::{
  Button, ColorImage, Image, Label, RichText, TextureHandle, TextureOptions, Ui, Vec2, Widget,
  load::SizedTexture,
};
use image::ImageReader;

use crate::{
  App,
  widgets::colors::{DARK, INFO},
};

// Four lookup tables generated by build script (see "gen_name_tables()" in "build.rs")
// + keyboard images
include!(concat!(env!("OUT_DIR"), "/codegen_name.rs"));

// + 14C -> 500, 64C, 798, 8E4, A30, B7C, CC8
const NAME_ADDRESS: u32 = 0x0200_0500;
const PC_NAMES: [&str; 7] = [
  "罗宾",
  "杰拉德",
  "伊万",
  "梅雅莉",
  "加西亚",
  "加斯敏",
  "西芭",
];
// 23, 24, 3C, 3D, 3E, 40, 5B, 5C, 5D, 5E, 7B, 7C, 7D
const SPECIAL_CHARS: [char; 13] = [
  '#', '$', '<', '=', '>', '@', '[', '￥', ']', '^', '{', '|', '}',
];

const DESC_C3: &str = r"该功能仅支持《黄金太阳 开启的封印》新汉化版，主要面向自定义中文名（但也支持中日英混合）。
请在输入框中输入至少一个角色的名字，再点击“运行”即可在下方的输出区域展示如何输入自定义名。

注：
⒈ 在“运行”后点击“复制”按钮，输出内容将会复制到剪贴板，之后便可粘贴到记事本进行查看。
⒉ 若想命名初代主角团其他的三位成员，请在起名界面连按三下“Select”键，成功后可听到提示音。
⒊ 若想命名最后的三位角色，请接着上条继续输入⬆⬇⬆⬇⬅➡⬅➡⬆➡⬇⬅⬆和“Select”，成功后可听到提示音。";

impl App {
  pub fn show_c3(&mut self, ui: &mut Ui) {
    Label::new(DESC_C3).selectable(false).ui(ui);

    egui::Grid::new("ID_GRID_C3")
      .num_columns(2)
      .spacing([40.0, 4.0])
      .striped(true)
      .show(ui, |ui| {
        for (i, ele) in PC_NAMES.iter().enumerate() {
          Label::new(*ele)
            .selectable(false)
            .ui(ui)
            .on_hover_text(format!("{ele}的自定义角色名。"));
          ui.add(
            egui::TextEdit::singleline(self.new_pc_names.get_mut(i).unwrap())
              .char_limit(5)
              .hint_text("请填写名字")
              .desired_width(f32::INFINITY),
          );
          ui.end_row();
        }
      });
  }

  pub fn run_c3(&mut self) {
    self.out_log_c3.clear();
    let mut first_run = true;

    for (index, pc_name_new) in self.new_pc_names.iter().enumerate() {
      if pc_name_new.is_empty() {
        continue;
      }

      if !first_run {
        self.out_log_c3.push_str("\n\n");
      }

      let pc_name = PC_NAMES[index];
      let _ = writeln!(self.out_log_c3, "{pc_name}");
      let char_vec: Vec<char> = pc_name_new.chars().collect();
      let mut invalid_flag = false;
      let mut name_bytes = [0; 10];
      let mut name_index = 0;

      self.out_log_c3.push_str("起名界面的输入方式：\n");
      for c in char_vec {
        if BASE_CHARACTERS_MAP.contains_key(&c) && !SPECIAL_CHARS.contains(&c) {
          let num = BASE_CHARACTERS_MAP.get(&c).unwrap();
          name_bytes[name_index] = *num;
          name_index += 1;

          let _ = writeln!(self.out_log_c3, "{c}：{c}");
        } else if DAKUTEN_KANA_MAP.contains_key(&c) {
          let string_value = DAKUTEN_KANA_MAP.get(&c).unwrap();

          for value in string_value.chars() {
            let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
            name_bytes[name_index] = *num;
            name_index += 1;
          }

          let _ = writeln!(
            self.out_log_c3,
            "{c}：{}",
            DAKUTEN_KANA_MAP.get(&c).unwrap()
          );
        } else if COMMON_HANZI_MAP.contains_key(&c) {
          let string_value = COMMON_HANZI_MAP.get(&c).unwrap();

          for value in string_value.chars() {
            let num = BASE_CHARACTERS_MAP.get(&value).unwrap();
            name_bytes[name_index] = *num;
            name_index += 1;
          }

          let _ = writeln!(
            self.out_log_c3,
            "{c}：{}",
            COMMON_HANZI_MAP.get(&c).unwrap()
          );
        } else if SPECIAL_HANZI_MAP.contains_key(&c) {
          let num = SPECIAL_HANZI_MAP.get(&c).unwrap();
          let num_bytes = num.to_be_bytes();
          name_bytes[name_index] = num_bytes[0];
          name_bytes[name_index + 1] = num_bytes[1];
          name_index += 2;

          let _ = writeln!(
            self.out_log_c3,
            "{c}：汉化版字库中包含该字符，但无法在起名界面中正常输入，码值为0x{:04X}",
            SPECIAL_HANZI_MAP.get(&c).unwrap()
          );
        } else if SPECIAL_CHARS.contains(&c) {
          invalid_flag = true;
          let _ = writeln!(self.out_log_c3, "{c}：汉化版的控制符，不能单独使用！");
        } else {
          invalid_flag = true;
          let _ = writeln!(self.out_log_c3, "{c}：汉化版字库中不包含该字符！");
        }
      }

      if invalid_flag {
        let _ = writeln!(
          self.out_log_c3,
          "由于存在不可用的字符，故不展示{pc_name}自定义名字所对应的十六进制值和金手指！"
        );
      } else {
        self.out_log_c3.push_str("十六进制值：\n");
        let len = name_bytes.len();
        for (i, name_byte) in name_bytes.iter().enumerate() {
          if i + 1 == len {
            let _ = writeln!(self.out_log_c3, "{name_byte:02X}");
          } else {
            let _ = write!(self.out_log_c3, "{name_byte:02X} ");
          }
        }

        self.out_log_c3.push_str("金手指：\n");
        for i in 0..3 {
          if i == 2 {
            let j = i as usize;
            let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
            let value = u16::from_le_bytes([name_bytes[j * 4], name_bytes[j * 4 + 1]]);
            let _ = writeln!(self.out_log_c3, "{address:08X}:{value:04X}");
          } else {
            let j = i as usize;
            let address = NAME_ADDRESS + u32::try_from(index).unwrap() * 0x14C + i * 4;
            let value = u32::from_le_bytes([
              name_bytes[j * 4],
              name_bytes[j * 4 + 1],
              name_bytes[j * 4 + 2],
              name_bytes[j * 4 + 3],
            ]);
            let _ = writeln!(self.out_log_c3, "{address:08X}:{value:08X}");
          }
        }
      }

      if first_run {
        first_run = false;
      }
    }
  }

  pub fn show_log_c3(&mut self, ui: &mut Ui) {
    let log_vec: Vec<&str> = self.out_log_c3.split('\n').collect();
    for single_line in log_vec {
      if single_line.contains("：")
        && (single_line.chars().count() == 4 || single_line.chars().count() == 3)
      {
        let char_vec: Vec<&str> = single_line.split('：').collect();
        ui.horizontal(|ui| {
          Label::new(format!("{}：", char_vec.first().unwrap()))
            .selectable(false)
            .ui(ui);
          for char_btn in char_vec.get(1).unwrap().chars() {
            ui.add(Button::new(RichText::new(char_btn).color(DARK)).fill(INFO))
              .on_hover_ui(|ui| {
                let char_index = BASE_CHARACTERS_MAP.get(&char_btn).unwrap();
                let (tex, size) = get_name_keyboard_img(ui, *char_index);
                let width = size[0] * 2.0;
                let height = size[1] * 2.0;
                let a = SizedTexture::new(tex.id(), Vec2::new(width, height));
                ui.add(Image::new(a).max_height(208.0));
              });
          }
        });
      } else {
        Label::new(single_line).selectable(false).ui(ui);
      }
    }
  }
}

fn get_name_keyboard_img(ui: &egui::Ui, char_index: u8) -> (TextureHandle, [f32; 2]) {
  let raw_data = *KEYBOARD_IMG_MAP.get(&char_index).unwrap();
  let mut reader = ImageReader::new(Cursor::new(raw_data));
  reader.set_format(image::ImageFormat::Png);
  let image = reader.decode().unwrap();
  let size = [image.width() as _, image.height() as _];
  let image_buffer = image.to_rgba8();
  let pixels = image_buffer.as_flat_samples();

  let color_image = ColorImage::from_rgba_unmultiplied(size, pixels.as_slice());
  (
    ui.load_texture(
      format!("name_kbd_{char_index:02X}"),
      color_image,
      TextureOptions::NEAREST,
    ),
    [size[0] as f32, size[1] as f32],
  )
}
